//! 🧪️ Shared reference-only ownership witnesses drive actual native relational projection and reconstruction.
use super::*;
fn control<'a>(callback:&'a mut dyn FnMut(store::sqlite_snapshot::SqliteSnapshotProgress)->bool)->SqliteSnapshotControl<'a>{SqliteSnapshotControl::new(callback,Default::default())}
fn fixture()->serde_json::Value{serde_json::from_str(include_str!("🔣️.json")).unwrap()}
fn document()->LayoutSnapshot{let corpus:serde_json::Value=serde_json::from_str(include_str!("../../../../🧪️tests/🧫️fixtures/✅️validation/🔣️.json")).unwrap();let mut snapshot:LayoutSnapshot=semio_framework_pack_json::from_json_str(&corpus["base"].to_string(),semio_framework_pack_json::JsonMemberPolicy::Reject).unwrap();while snapshot.pages.len()<2{let mut page=snapshot.pages[0].clone();page.id=format!("page-{}",snapshot.pages.len());snapshot.pages.push(page)}let fixture=fixture();for index in 0..3{let row=&fixture["members"][index];let member=LayoutDrawingMember{handle:store::os_store::artifact_child::ArtifactChild::new(row["childId"].as_str().unwrap().into(),semio_framework_artifact_reference::ArtifactRef{dialect:semio_framework_artifact_reference::ArtifactDialect{artifact_kind:"s.draw.drawing".into(),standard:"1".into(),subset:"*".into()},artifact_id:row["artifactId"].as_str().unwrap().into()})};if index==0{snapshot.background_drawing=Some(member)}else{snapshot.pages[index-1].background_drawing=Some(member)}}snapshot}
#[test]
fn genuine_reference_rows_round_trip_without_child_geometry_or_inline_codec(){let source=document();let mut callback=|_|true;let database=project(&source,&mut control(&mut callback)).unwrap();assert!(database.tables.iter().all(|table|table.name.starts_with("layout_")));let table=database.table("layout_drawing_member").unwrap();assert_eq!(table.rows.len(),fixture()["members"].as_array().unwrap().len());let restored=reconstruct(&database,&mut control(&mut callback)).unwrap();assert_eq!(restored,source);for case in 0..7{let mut broken=database.clone();let table=broken.tables.iter_mut().find(|table|table.name=="layout_drawing_member").unwrap();match case{0=>table.rows[0].values[2]=store::sqlite_snapshot::SqliteValue::Integer(1),1=>table.rows[0].values[1]=store::sqlite_snapshot::SqliteValue::Null,2=>table.rows[1].values[2]=store::sqlite_snapshot::SqliteValue::Integer(999),3=>table.rows[1].values[4]=store::sqlite_snapshot::SqliteValue::Text("s.stdio.semio".into()),4=>table.rows[1].values[3]=table.rows[0].values[3].clone(),5=>table.rows[1].values[7]=table.rows[0].values[7].clone(),_=>table.rows[2].values[2]=table.rows[1].values[2].clone()}assert!(reconstruct(&broken,&mut control(&mut callback)).is_err(),"case {case}");}}
